import React, { useState, useEffect } from 'react';
import axios from 'axios';

const API_URL = 'http://127.0.0.1:5555';

const App = () => {
  const [personnels, setPersonnels] = useState([]);
  const [newPersonnel, setNewPersonnel] = useState({
    first_name: '', last_name: '', rank: '', role_id: '', unit_id: '', squad_id: '', phone_number: '', email: '', age: '', joining_date: ''
  });
  const [editingPersonnel, setEditingPersonnel] = useState(null);

  // Fetch all personnels
  const fetchPersonnels = async () => {
    try {
      const response = await axios.get(`${API_URL}/personnels`);
      setPersonnels(response.data);
    } catch (error) {
      console.error('Error fetching personnels:', error);
    }
  };

  useEffect(() => {
    fetchPersonnels();
  }, []);

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!newPersonnel.first_name || !newPersonnel.last_name || !newPersonnel.rank) {
      alert('Please fill in all fields');
      return;
    }

    try {
      if (editingPersonnel) {
        await axios.put(`${API_URL}/personnels/${editingPersonnel.id}`, newPersonnel);
        setEditingPersonnel(null);
      } else {
        await axios.post(`${API_URL}/personnels`, newPersonnel);
      }

      setNewPersonnel({
        first_name: '', last_name: '', rank: '', role_id: '', unit_id: '', squad_id: '', phone_number: '', email: '', age: '', joining_date: ''
      });
      fetchPersonnels();
    } catch (error) {
      console.error('Error adding/updating personnel:', error);
    }
  };

  const handleEdit = (personnel) => {
    setEditingPersonnel(personnel);
    setNewPersonnel({
      first_name: personnel.first_name,
      last_name: personnel.last_name,
      rank: personnel.rank,
      role_id: personnel.role_id,
      unit_id: personnel.unit_id,
      squad_id: personnel.squad_id,
      phone_number: personnel.phone_number,
      email: personnel.email,
      age: personnel.age,
      joining_date: personnel.joining_date,
    });
  };

  const handleDelete = async (id) => {
    try {
      await axios.delete(`${API_URL}/personnels/${id}`);
      fetchPersonnels();
    } catch (error) {
      console.error('Error deleting personnel:', error);
    }
  };

  return (
    <div className="App">
      <h1>Personnel Management</h1>

      <form onSubmit={handleSubmit}>
        <input
          type="text"
          placeholder="First Name"
          value={newPersonnel.first_name}
          onChange={(e) => setNewPersonnel({ ...newPersonnel, first_name: e.target.value })}
        />
        <input
          type="text"
          placeholder="Last Name"
          value={newPersonnel.last_name}
          onChange={(e) => setNewPersonnel({ ...newPersonnel, last_name: e.target.value })}
        />
        <input
          type="text"
          placeholder="Rank"
          value={newPersonnel.rank}
          onChange={(e) => setNewPersonnel({ ...newPersonnel, rank: e.target.value })}
        />
        {/* Other input fields for age, phone_number, email, role_id, unit_id, squad_id, and joining_date */}
        <button type="submit">{editingPersonnel ? 'Update' : 'Add'} Personnel</button>
      </form>

      <table>
        <thead>
          <tr>
            <th>First Name</th>
            <th>Last Name</th>
            <th>Rank</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody>
          {personnels.map((personnel) => (
            <tr key={personnel.id}>
              <td>{personnel.first_name}</td>
              <td>{personnel.last_name}</td>
              <td>{personnel.rank}</td>
              <td>
                <button onClick={() => handleEdit(personnel)}>Edit</button>
                <button onClick={() => handleDelete(personnel.id)}>Delete</button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};

export default App;
